      "card_ids": ["C187","C165","C161","C177","C181","C142","C153","C178"]
    },
    {
      "claim": "L4 Caco-2 data for related small basic amines (norephedrine 9.75-10.0 x 10^-6 cm/s, cathine 8.25-9.96 x 10^-6 cm/s, cathinone 12.03 x 10^-6 cm/s) also indicate high permeability.",
      "card_ids": ["C159","C167","C155","C175","C104","C93","C130","C115"]
    },
    {
      "claim": "L6 hepatic-clearance records are mostly for non-query chemotypes (adamantane amides, mexiletine, amphetamine, isopropylamine, terpenes); none is a direct rimantadine hepatic-clearance or F measurement, and high CLint in some adamantane amides is not transferable to the primary-amine rimantadine.",
      "card_ids": ["C237","C204","C201","C215","C212","C200","C236"]
    },
    {
      "claim": "No affirmative threshold-relevant evidence supports F < 20%; the physicochemical prior (low MW, low TPSA, favorable solubility) and analog absorption/efflux data support F >= 20%.",
      "card_ids": ["C185","C157","C159","C104"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
